insert into public.sources(id,org,title,url,use_ar,use_en,reviewed) values
(39,'NIH Office of Dietary Supplements','Selenium: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/','الاحتياج والحد الأعلى وأعراض الزيادة والتداخلات','Needs, upper limit, toxicity, interactions',false),
(40,'NIH Office of Dietary Supplements','Copper: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Copper-HealthProfessional/','الاحتياج والحد الأعلى وتأثير الزنك','Needs, upper limit, zinc effect',false),
(41,'NIH Office of Dietary Supplements','Potassium: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Potassium-HealthProfessional/','الاحتياج الكافي والتداخلات وتحذير الكلى','Adequate intake, interactions, kidney caution',false),
(42,'NIH Office of Dietary Supplements','Omega-3 Fatty Acids: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Omega3FattyAcids-HealthProfessional/','الاحتياج الكافي والكميات الآمنة والتداخل مع الوارفارين','Adequate intake, safe amounts, warfarin',false),
(43,'NIH Office of Dietary Supplements','Riboflavin: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Riboflavin-HealthProfessional/','الاحتياج','Needs',false),
(44,'NIH Office of Dietary Supplements','Choline: Fact Sheet for Health Professionals','https://ods.od.nih.gov/factsheets/Choline-HealthProfessional/','الاحتياج الكافي والحد الأعلى','Adequate intake, upper limit',false);
insert into public.nutrients(id,builtin,sort,name_ar,name_en,hint_ar,hint_en,unit,dose_rows,note_ar,note_en,source_ids,reviewed) values
('selenium',false,170,'السيلينيوم','Selenium','مضاد للأكسدة والغدة الدرقية','Antioxidant, thyroid','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "15–20", "ul": "45–60"}, {"a0": 1, "a1": 3, "sx": "all", "rda": "20", "ul": "90"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "30", "ul": "150"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "40", "ul": "280"}, {"a0": 14, "a1": 110, "sx": "all", "rda": "55", "ul": "400"}, {"a0": 14, "a1": 50, "sx": "p", "rda": "60", "ul": "400"}, {"a0": 14, "a1": 50, "sx": "l", "rda": "70", "ul": "400"}]'::jsonb,'الأعراض الأكثر شيوعاً لزيادة السيلينيوم المزمنة تساقط الشعر وهشاشة الأظافر أو سقوطها، وقد تسبب طفحاً جلدياً وغثياناً وإسهالاً وتعباً وتهيجاً واضطرابات عصبية. الحد الأعلى لا ينطبق على العلاج تحت إشراف الطبيب. للرضّع: الاحتياج 15 لأول 6 أشهر و20 من 7 إلى 12 شهراً، والحد الأعلى 45 ثم 60.','The most common signs of chronic excess are hair loss and brittle or lost nails; it can also cause skin rash, nausea, diarrhea, fatigue, irritability and nervous system problems. The upper limit does not apply under a physician''s care. Infants: need 15 for 0–6 months and 20 for 7–12 months; upper limit 45 then 60.','{39}',false),
('copper',false,180,'النحاس','Copper','تكوين الدم والأعصاب','Blood and nerves','mcg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "200–220", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "340", "ul": "1,000"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "440", "ul": "3,000"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "700", "ul": "5,000"}, {"a0": 14, "a1": 18, "sx": "all", "rda": "890", "ul": "8,000"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "1,000", "ul": "8,000"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "1,300", "ul": "8,000"}, {"a0": 19, "a1": 110, "sx": "all", "rda": "900", "ul": "10,000"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "1,000", "ul": "10,000"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "1,300", "ul": "10,000"}]'::jsonb,'لا يُعرف للنحاس تداخل دوائي مهم سريرياً. الإفراط في مكملات الزنك قد يسبب نقص النحاس. الحد الأعلى لا ينطبق على العلاج تحت إشراف طبي. للرضّع: 200 لأول 6 أشهر و220 من 7 إلى 12 شهراً، ومصدرهم حليب الأم أو الحليب الصناعي والغذاء فقط.','Copper has no known clinically relevant drug interactions. Excessive zinc supplements can cause copper deficiency. The upper limit does not apply under medical supervision. Infants: 200 for 0–6 months and 220 for 7–12 months; breast milk, formula and food should be their only sources.','{40}',false),
('potassium',false,190,'البوتاسيوم','Potassium','القلب والعضلات','Heart and muscles','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "400–860", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "2,000", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "2,300", "ul": ""}, {"a0": 9, "a1": 13, "sx": "m", "rda": "2,500", "ul": ""}, {"a0": 9, "a1": 13, "sx": "f", "rda": "2,300", "ul": ""}, {"a0": 14, "a1": 18, "sx": "m", "rda": "3,000", "ul": ""}, {"a0": 14, "a1": 18, "sx": "f", "rda": "2,300", "ul": ""}, {"a0": 14, "a1": 18, "sx": "p", "rda": "2,600", "ul": ""}, {"a0": 14, "a1": 18, "sx": "l", "rda": "2,500", "ul": ""}, {"a0": 19, "a1": 110, "sx": "m", "rda": "3,400", "ul": ""}, {"a0": 19, "a1": 110, "sx": "f", "rda": "2,600", "ul": ""}, {"a0": 19, "a1": 50, "sx": "p", "rda": "2,900", "ul": ""}, {"a0": 19, "a1": 50, "sx": "l", "rda": "2,800", "ul": ""}]'::jsonb,'قيم احتياج كافٍ (AI)، ولا يوجد حد أعلى. لا تنطبق هذه القيم على من لديهم ضعف في طرح البوتاسيوم بسبب أمراض الكلى أو أدوية معينة، فقد يحدث لديهم ارتفاع البوتاسيوم حتى بكميات أقل من الاحتياج. الكميات العالية جداً من المكملات أو بدائل الملح قد تسبب ارتفاعاً حاداً في البوتاسيوم حتى لدى الأصحاء.','Adequate intakes (AI); no upper limit. These values do not apply to people whose potassium excretion is impaired by kidney disease or certain medicines; they can develop high potassium even below the AI. Very high amounts from supplements or salt substitutes can cause acute hyperkalemia even in healthy people.','{41}',false),
('omega3',false,200,'أوميغا-3','Omega-3','الأحماض الدهنية الأساسية','Essential fatty acids','g','[{"a0": 0, "a1": 0, "sx": "all", "rda": "0.5", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "0.7", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "0.9", "ul": ""}, {"a0": 9, "a1": 13, "sx": "m", "rda": "1.2", "ul": ""}, {"a0": 9, "a1": 13, "sx": "f", "rda": "1.0", "ul": ""}, {"a0": 14, "a1": 110, "sx": "m", "rda": "1.6", "ul": ""}, {"a0": 14, "a1": 110, "sx": "f", "rda": "1.1", "ul": ""}, {"a0": 14, "a1": 50, "sx": "p", "rda": "1.4", "ul": ""}, {"a0": 14, "a1": 50, "sx": "l", "rda": "1.3", "ul": ""}]'::jsonb,'القيم بالغرام من حمض ألفا لينولينيك (ALA)، وللرضّع من مجموع أوميغا-3. لا يوجد حد أعلى رسمي. ترى EFSA أن تناول EPA وDHA معاً حتى نحو 5 غرامات يومياً آمن على المدى الطويل، وتعتبر FDA المكملات التي لا تتجاوز 5 غرامات يومياً آمنة.','Grams of alpha-linolenic acid (ALA); for infants, total omega-3s. No official upper limit. EFSA considers combined EPA and DHA up to about 5 g/day safe long term, and FDA considers supplements providing no more than 5 g/day safe.','{42}',false),
('b2',false,210,'فيتامين B2','Vitamin B2','الريبوفلافين','Riboflavin','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "0.3–0.4", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "0.5", "ul": ""}, {"a0": 4, "a1": 8, "sx": "all", "rda": "0.6", "ul": ""}, {"a0": 9, "a1": 13, "sx": "all", "rda": "0.9", "ul": ""}, {"a0": 14, "a1": 18, "sx": "m", "rda": "1.3", "ul": ""}, {"a0": 14, "a1": 18, "sx": "f", "rda": "1.0", "ul": ""}, {"a0": 14, "a1": 18, "sx": "p", "rda": "1.4", "ul": ""}, {"a0": 14, "a1": 18, "sx": "l", "rda": "1.6", "ul": ""}, {"a0": 19, "a1": 110, "sx": "m", "rda": "1.3", "ul": ""}, {"a0": 19, "a1": 110, "sx": "f", "rda": "1.1", "ul": ""}, {"a0": 19, "a1": 50, "sx": "p", "rda": "1.4", "ul": ""}, {"a0": 19, "a1": 50, "sx": "l", "rda": "1.6", "ul": ""}]'::jsonb,'لا يوجد حد أعلى، لعدم تسجيل آثار ضارة حتى مع 400 ملغ يومياً لمدة 3 أشهر على الأقل. لا يُعرف له تداخل دوائي مهم سريرياً. للرضّع: 0.3 ملغ لأول 6 أشهر و0.4 من 7 إلى 12 شهراً.','No upper limit, since no adverse effects were reported even at 400 mg/day for at least 3 months. No known clinically relevant drug interactions. Infants: 0.3 mg for 0–6 months and 0.4 mg for 7–12 months.','{43}',false),
('choline',false,220,'الكولين','Choline','الكبد والدماغ','Liver and brain','mg','[{"a0": 0, "a1": 0, "sx": "all", "rda": "125–150", "ul": ""}, {"a0": 1, "a1": 3, "sx": "all", "rda": "200", "ul": "1,000"}, {"a0": 4, "a1": 8, "sx": "all", "rda": "250", "ul": "1,000"}, {"a0": 9, "a1": 13, "sx": "all", "rda": "375", "ul": "2,000"}, {"a0": 14, "a1": 18, "sx": "m", "rda": "550", "ul": "3,000"}, {"a0": 14, "a1": 18, "sx": "f", "rda": "400", "ul": "3,000"}, {"a0": 14, "a1": 18, "sx": "p", "rda": "450", "ul": "3,000"}, {"a0": 14, "a1": 18, "sx": "l", "rda": "550", "ul": "3,000"}, {"a0": 19, "a1": 110, "sx": "m", "rda": "550", "ul": "3,500"}, {"a0": 19, "a1": 110, "sx": "f", "rda": "425", "ul": "3,500"}, {"a0": 19, "a1": 50, "sx": "p", "rda": "450", "ul": "3,500"}, {"a0": 19, "a1": 50, "sx": "l", "rda": "550", "ul": "3,500"}]'::jsonb,'قيم احتياج كافٍ (AI). الكميات العالية قد تسبب رائحة جسم تشبه السمك وقيئاً وتعرقاً ولعاباً زائدين وانخفاض ضغط الدم وسمية الكبد. لا يُعرف له تداخل دوائي مهم سريرياً. للرضّع: 125 لأول 6 أشهر و150 من 7 إلى 12 شهراً، ومصدرهم حليب الأم أو الحليب الصناعي والغذاء فقط.','Adequate intakes (AI). High intakes can cause fishy body odor, vomiting, excessive sweating and salivation, low blood pressure and liver toxicity. No known clinically relevant drug interactions. Infants: 125 for 0–6 months and 150 for 7–12 months; breast milk, formula and food should be their only sources.','{44}',false);
insert into public.interactions(nutrient_id,supp_ar,supp_en,with_ar,with_en,desc_ar,desc_en,severity,source_ids,sort,reviewed) values
('selenium','السيلينيوم','Selenium','Cisplatin','Cisplatin','قد يخفض مستوى السيلينيوم في الشعر والمصل والأهمية السريرية غير معروفة، والأدلة على أن مكملاته تقلل سمية الدواء غير كافية','May lower selenium in hair and serum, of unknown clinical significance; evidence that supplements reduce its toxicity is insufficient','minor','{39}',2000,false),
('copper','النحاس','Copper','الزنك بجرعات عالية','High-dose zinc','الإفراط في مكملات الزنك قد يسبب نقص النحاس؛ سُجّل انخفاض مؤشراته مع نحو 60 ملغ زنك يومياً لمدة تصل إلى 10 أسابيع','Excessive zinc supplements can cause copper deficiency; markers fell with about 60 mg zinc daily for up to 10 weeks','moderate','{40}',2010,false),
('potassium','البوتاسيوم','Potassium','مثبطات ACE وحاصرات مستقبلات الأنجيوتنسين (Benazepril وLosartan)','ACE inhibitors and ARBs (benazepril, losartan)','تقلل طرح البوتاسيوم وقد تسبب ارتفاعه؛ يُراقب المستوى خاصة مع ضعف الكلى','Reduce potassium excretion and can cause hyperkalemia; monitor levels, especially with impaired kidney function','major','{41}',2020,false),
('potassium','البوتاسيوم','Potassium','المدرات الحافظة للبوتاسيوم (Amiloride وSpironolactone)','Potassium-sparing diuretics (amiloride, spironolactone)','تقلل طرح البوتاسيوم وقد تسبب ارتفاعه؛ يُراقب المستوى خاصة مع ضعف الكلى','Reduce potassium excretion and can cause hyperkalemia; monitor levels, especially with impaired kidney function','major','{41}',2030,false),
('potassium','البوتاسيوم','Potassium','مدرات Loop وThiazide (Furosemide وBumetanide وChlorothiazide وMetolazone)','Loop and thiazide diuretics (furosemide, bumetanide, chlorothiazide, metolazone)','تزيد طرح البوتاسيوم وقد تسبب انخفاضه؛ يُراقب المستوى ويُبدأ المكمل عند الحاجة','Increase potassium excretion and can cause hypokalemia; monitor levels and supplement if warranted','moderate','{41}',2040,false),
('omega3','أوميغا-3','Omega-3','Warfarin ومضادات التخثر','Warfarin and anticoagulants','زيت السمك بجرعات عالية قد يطيل زمن التخثر (INR)، ومعظم الأبحاث تشير إلى أن 3 إلى 6 غرامات يومياً لا تؤثر بشكل ملحوظ؛ توصي النشرات المعتمدة بمراقبة INR دورياً','High-dose fish oil might prolong clotting time (INR), though most research shows 3–6 g/day has no significant effect; approved labels advise periodic INR monitoring','moderate','{42}',2050,false),
('ca','الكالسيوم','Calcium','Dolutegravir','Dolutegravir','مكملات الكالسيوم قد تخفض مستواه في الدم بشكل كبير؛ يؤخذ الدواء قبل الكالسيوم بساعتين أو بعده بـ 6 ساعات','Calcium supplements can substantially lower its blood levels; take the drug 2 hours before or 6 hours after calcium','major','{18}',2060,false),
('ca','الكالسيوم','Calcium','Lithium','Lithium','الاستعمال الطويل قد يسبب ارتفاع الكالسيوم، ومكملات الكالسيوم قد تزيد هذا الخطر','Long-term use can cause hypercalcemia, and calcium supplements could increase this risk','moderate','{18}',2070,false),
('ca','الكالسيوم','Calcium','الكينولونات (Ciprofloxacin وMoxifloxacin)','Quinolones (ciprofloxacin, moxifloxacin)','الكالسيوم يقلل امتصاص المضاد؛ يؤخذ المضاد قبل الكالسيوم بساعتين أو بعده بساعتين','Calcium reduces absorption of the antibiotic; take it 2 hours before or 2 hours after calcium','moderate','{18}',2080,false),
('fe','الحديد','Iron','Levodopa','Levodopa','قد يقلل الحديد امتصاص Levodopa وبالتالي فعاليته','Iron may reduce levodopa absorption and so its effectiveness','moderate','{15}',2090,false),
('fe','الحديد','Iron','مثبطات مضخة البروتون (Omeprazole وLansoprazole)','Proton pump inhibitors (omeprazole, lansoprazole)','تقلل امتصاص الحديد، ومرضى نقص الحديد الذين يتناولونها قد لا يستجيبون جيداً للمكمل','Reduce iron absorption; iron-deficient patients taking them may respond poorly to supplements','minor','{15}',2100,false),
('mg','المغنيسيوم','Magnesium','المدرات الحافظة للبوتاسيوم (Amiloride وSpironolactone)','Potassium-sparing diuretics (amiloride, spironolactone)','تقلل طرح المغنيسيوم، عكس المدرات الأخرى','Reduce magnesium excretion, the opposite of other diuretics','minor','{20}',2110,false);
